// HasTargetGroup applies the HasEdge predicate on the "target_group" edge.
func HasTargetGroup() predicate.GroupBuyPlan {
	return predicate.GroupBuyPlan(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TargetGroupTable, TargetGroupColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTargetGroupWith applies the HasEdge predicate on the "target_group" edge with a given conditions (other predicates).
func HasTargetGroupWith(preds ...predicate.Group) predicate.GroupBuyPlan {
	return predicate.GroupBuyPlan(func(s *sql.Selector) {
		step := newTargetGroupStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

