// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GroupBuyPlan) predicate.GroupBuyPlan {
	return predicate.GroupBuyPlan(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GroupBuyPlan) predicate.GroupBuyPlan {
	return predicate.GroupBuyPlan(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GroupBuyPlan) predicate.GroupBuyPlan {
	return predicate.GroupBuyPlan(sql.NotPredicates(p))
}
